"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[9349],{883(e,n,i){i.r(n),i.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>h,frontMatter:()=>r,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"content/ecosystem-vision-and-fundamentals/governance-and-operation-model","title":"governance-and-operation-model","description":"This section presents the core principles and foundational concepts for the","source":"@site/architecture-proposal/content/ecosystem-vision-and-fundamentals/governance-and-operation-model.md","sourceDirName":"content/ecosystem-vision-and-fundamentals","slug":"/content/ecosystem-vision-and-fundamentals/governance-and-operation-model","permalink":"/rowallet-blueprint/content/ecosystem-vision-and-fundamentals/governance-and-operation-model","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"format":"md"},"sidebar":"blueprint","previous":{"title":"RO Wallet Value Proposition","permalink":"/rowallet-blueprint/content/ecosystem-vision-and-fundamentals/EUDI-value-proposition"},"next":{"title":"index","permalink":"/rowallet-blueprint/content/ecosystem-concepts/"}}');var s=i(4848),a=i(8453);const r={format:"md"},o="RO Wallet Ecosystem Governance and Operating Model Fundamentals",l={},c=[{value:"Empowering Citizens and Residents: Real Choices for Self-Determination with Safeguards in the Digital Realm",id:"empowering-citizens-and-residents-real-choices-for-self-determination-with-safeguards-in-the-digital-realm",level:2},{value:"Driving Societal Progress: The RO Wallet Infrastructure is a Foundational Digital Public Infrastructure for Society",id:"driving-societal-progress-the-ro-wallet-infrastructure-is-a-foundational-digital-public-infrastructure-for-society",level:2},{value:"Splitting Responsibilities: Differentiation between a Government, Cooperative and Competitive Space for Efficient Collaboration",id:"splitting-responsibilities-differentiation-between-a-government-cooperative-and-competitive-space-for-efficient-collaboration",level:2},{value:"EUDI Wallet Providers",id:"eudi-wallet-providers",level:3},{value:"Ecosystem (Technology) Service Providers",id:"ecosystem-technology-service-providers",level:3},{value:"Domain organization and governance",id:"domain-organization-and-governance",level:3},{value:"Ecosystem Onboarding: Consolidating Information, Centralizing Access, and Enhancing Transparency to Prevent Misuse",id:"ecosystem-onboarding-consolidating-information-centralizing-access-and-enhancing-transparency-to-prevent-misuse",level:2},{value:"Level-Playing Field Regulation: The Foundation for User Choice and Fair Competition Among Ecosystem Actors",id:"level-playing-field-regulation-the-foundation-for-user-choice-and-fair-competition-among-ecosystem-actors",level:2}];function d(e){const n={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"ro-wallet-ecosystem-governance-and-operating-model-fundamentals",children:"RO Wallet Ecosystem Governance and Operating Model Fundamentals"})}),"\n",(0,s.jsx)(n.p,{children:"This section presents the core principles and foundational concepts for the\ndesign and implementation of the RO Wallet Ecosystem governance and\nRO Wallet infrastructure operating model based on the EU eIDAS regulation\nadapted to the Romanian context. This document is created iteratively and is\ncontinuously expanded and adapted. We value your feedback and suggestions and\nwill integrate them into our FAQ and future updates."}),"\n",(0,s.jsx)(n.h2,{id:"empowering-citizens-and-residents-real-choices-for-self-determination-with-safeguards-in-the-digital-realm",children:"Empowering Citizens and Residents: Real Choices for Self-Determination with Safeguards in the Digital Realm"}),"\n",(0,s.jsxs)(n.p,{children:["During the initial phase, the RO Wallet solution will be\navailable to ",(0,s.jsx)(n.strong,{children:"Romanian citizens who hold an electronic identity card (CEI)"}),".\nExtending the availability of the RO Wallet solution to Romanian citizens holding other identity documents, and to foreign residents in\nRomania is being assessed and considered for a subsequent development phase\nduring 2027."]}),"\n",(0,s.jsx)(n.p,{children:"The aim of this chapter is to provide an overview about the value proposition of\nthe RO Wallet Ecosystem for citizens and residents.RO Wallet empowers users by simplifying access to services,\nreducing administrative burdens, and offering full control over personal data,\nwhile ensuring privacy, security, and legal recognition of electronic\nattestations and signatures across the EU. The RO Wallet Ecosystem provides\nthe following value for citizens and residents:"}),"\n",(0,s.jsx)(n.p,{children:"Comfort and efficiency"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Wallet as digital assistant for managing all kind of attestations in one place"}),"\n",(0,s.jsx)(n.li,{children:"Leaving physical documents at home"}),"\n",(0,s.jsx)(n.li,{children:"Good user experience"}),"\n",(0,s.jsx)(n.li,{children:"Simplified onboarding process for new services"}),"\n",(0,s.jsx)(n.li,{children:"Reduce administrative hurdles for users"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Better access to services"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Non-discriminatory access for all actors"}),"\n",(0,s.jsx)(n.li,{children:"Access to wide range of public and private services across the European Union\nboth online and offline"}),"\n",(0,s.jsx)(n.li,{children:"Opportunity to providing fully digitized business processes"}),"\n",(0,s.jsx)(n.li,{children:"Enable powers of representation (e.g. natural and legal persons)"}),"\n",(0,s.jsx)(n.li,{children:"Support of cross-border mobility"}),"\n",(0,s.jsx)(n.li,{children:"Interoperable e-government services"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Control and transparency over personal data"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Exercise their rights in the digital economy/society"}),"\n",(0,s.jsx)(n.li,{children:"Decide what personal data is shared with whom (digital identity under their\nsole control)"}),"\n",(0,s.jsx)(n.li,{children:"Identify the Relying Party the personal data is shared with (accountability of\nthe RP)"}),"\n",(0,s.jsx)(n.li,{children:"Identify the PID or (qualified) EAA provider from which the PID/EAA was issued"}),"\n",(0,s.jsx)(n.li,{children:"Access a summary of personal data exchanged with Relying Parties and\nPID/(Q)EAA providers, along with details of electronic signatures generated"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Enhanced privacy for sharing personal data digitally"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Enable privacy preserving techniques which ensure unlinkability, where the\nattestation of attributes does not require the identification of the user"}),"\n",(0,s.jsx)(n.li,{children:"Relying Parties are not allowed to force the identification of users without\nlegal basis and shall not refuse the use of pseudonyms, where the\nidentification of the user is not required by Union or national law"}),"\n",(0,s.jsx)(n.li,{children:"Support the pseudonymous use of services:Relying parties shall not refuse the\nuse of pseudonyms, where the identification of the user is not required by\nUnion or national law"}),"\n",(0,s.jsx)(n.li,{children:"Data minimization: only personal data that is absolutely required for the\nbusiness process is shared with Relying Parties"}),"\n",(0,s.jsx)(n.li,{children:"Compared to presenting physical documents, only data that is strictly needed\nis shared within the use electronic attestations"}),"\n",(0,s.jsx)(n.li,{children:"Unobservability \u2013 ensuring that neither the wallet provider nor the\n(qualified) EAA providers can monitor user activities."}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"High security level"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"High level of security and trustworthiness"}),"\n",(0,s.jsx)(n.li,{children:"Decentralized architecture with no single eID database for all users reducing\nimpact of data breaches (Romanian eID/ RO Wallet Ecosystem)"}),"\n",(0,s.jsx)(n.li,{children:"Protection against cybersecurity risks and cybercrime, identity theft and\nonline fraud19"}),"\n",(0,s.jsx)(n.li,{children:"Safeguarding personal information from unauthorized or fraudulent use"}),"\n",(0,s.jsx)(n.li,{children:"Support Strong User Authentication to replace user name/password\nauthentication"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Legal recognition and harmonization"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"The use of the RO Wallet is entirely voluntary, and individuals are free to\nchoose whether or not to use it, without facing any negative consequences"})}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Every citizen and resident has the right to get access to and to use RO Wallet\nfree of charge across all member states"}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Electronic attestations of attributes issued by the public sector have the\nsame legal value as paper attestations across the Union (for PubEAA)"}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Empower citizens and residents to fully benefit from digitalization"}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Free Qualified Electronic Signatures for non-professional use"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Provide citizens and residents with a reliable and legally recognized means to\nsign documents digitally"}),"\n",(0,s.jsx)(n.li,{children:"Provide citizens and residents with free of charge qualified electronic\nsignatures for non-professional purposes"}),"\n",(0,s.jsx)(n.li,{children:"Sign self-claimed assertions or attributes"}),"\n",(0,s.jsx)(n.li,{children:"Sign a power of attorney statement"}),"\n",(0,s.jsx)(n.li,{children:"Enable Relying Parties to request qualified electronic signatures from RO Wallet users, facilitating the digital signing of documents and transactions."}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"driving-societal-progress-the-ro-wallet-infrastructure-is-a-foundational-digital-public-infrastructure-for-society",children:"Driving Societal Progress: The RO Wallet Infrastructure is a Foundational Digital Public Infrastructure for Society"}),"\n",(0,s.jsx)(n.p,{children:"This chapter aims to provide an overview of the value proposition of the RO\nWallet Ecosystem for the Romanian society and explains why the Romanian government\nshould invest and drive the implementation of the RO Wallet Ecosystem."}),"\n",(0,s.jsx)(n.p,{children:"The digital transformation of Romanian Society shall empower the sovereignty of\ncitizens and residents in a digital space that is less prone to fraud and\nenables the creation of economic value. To establish the underlying ecosystem at\nlevel playing field shall be created for all RO Wallet Ecosystem actors - such\nas public and private service providers."}),"\n",(0,s.jsx)(n.p,{children:"Enable the digital transformation of Romanian Society"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Deploy wallet ecosystem as facilitator for the digital transformation"}),"\n",(0,s.jsx)(n.li,{children:"Provide at least one wallet solution independent of commercial success\ncriteria"}),"\n",(0,s.jsx)(n.li,{children:"Foster innovations as basis for a reliable digital infrastructure"}),"\n",(0,s.jsx)(n.li,{children:"Create a level playing field for all stakeholders in the ecosystem (fair\ncompetition)"}),"\n",(0,s.jsx)(n.li,{children:"Enable freedom of choice regarding the RO Wallet for citizens and residents\nto foster trust and innovation"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Improve the sovereignty of citizens and residents"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Empower citizens and residents to act independently and confidently in their\ndigital lives"}),"\n",(0,s.jsx)(n.li,{children:"Bridge the digital divide in our society through inclusive design"}),"\n",(0,s.jsx)(n.li,{children:"Avoid surveillance by design"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Establish an interconnected ecosystem between all EU member states"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Seamless and secure digital interactions across the EU for all ecosystem\nparticipants, esp. Users, Relying Parties and EAA Providers"}),"\n",(0,s.jsx)(n.li,{children:"EU wide non-discriminatory ecosystem access to all EUDI wallets for EAA\nProviders and Relying Parties"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Improve security and trust for the digital space"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Harmonized oversight and trust infrastructure"}),"\n",(0,s.jsx)(n.li,{children:"Ensure accountability of all stakeholders in the ecosystem"}),"\n",(0,s.jsx)(n.li,{children:"Reduce fraud and cybercrime"}),"\n",(0,s.jsx)(n.li,{children:"Protect users against unauthorized or fraudulent use of their digital\nidentities"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Foster economic value creation"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Enable public administrations and private organizations to make their\nprocesses more user friendly, transparent and efficient"}),"\n",(0,s.jsx)(n.li,{children:"Enable Relying Parties to reduce their operational costs linked to electronic\nidentification and authentication"}),"\n",(0,s.jsx)(n.li,{children:"Promote the secure digital transformation of SMEs"}),"\n",(0,s.jsx)(n.li,{children:"Facilitate easier access to services across borders, reduce administrative\nburdens"}),"\n",(0,s.jsx)(n.li,{children:"Enable commercial business models on top of the infrastructure"}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"splitting-responsibilities-differentiation-between-a-government-cooperative-and-competitive-space-for-efficient-collaboration",children:"Splitting Responsibilities: Differentiation between a Government, Cooperative and Competitive Space for Efficient Collaboration"}),"\n",(0,s.jsx)(n.p,{children:"The emergence of the RO Wallet Ecosystem requires a division of\nresponsibilities between government tasks (government space), public-private\ncooperation (cooperative space) and individual differentiation and\nspecialization (competitive space). Figure 1 provides an overview of the\nconceptual framework for the three responsibility spaces."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Responsibility Spaces.",src:i(5301).A+"",width:"1778",height:"678"})}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Figure 1: Mapping the responsibilities of the government, cooperative and\ncompetition space"})}),"\n",(0,s.jsx)(n.p,{children:'The government domain is dedicated to establishing the essential trust\ninfrastructure for the RO Wallet Ecosystem. It ensures regulatory oversight,\ncertification, enforcement, and the provision of public credentials, such as the\nPerson Identification Data (PID) or a mobile Driving License, to boost\ncredential sharing through the RO Wallet Ecosystem. The cooperative space\nbetween diverse public and private ecosystem actors aims to generate network\neffects through an acceptance network by offering a variety of domain-specific\ncredentials and integrating multiple organizational use cases. This approach\nensures a broad reach and drives widespread adoption of the public-private RO\nWallet Ecosystem. In this context, "public-private" means that the RO Wallet\nEcosystem extends beyond the public sector, encompassing the private sector,\nacademia, and civil society. Furthermore, collaboration is needed to create\ncommon standards that ensure interoperability, foster ease of use and lead to a\nharmonized ecosystem beyond technical and organizational silos. In addition,\nco-creation is essential to reducing barriers through an open process aimed to\ndevelop fundamental ecosystem components that serve shared interests (e.g., the\ncore RO Wallet). This approach helps lower overall costs for the RO Wallet\nEcosystem and its individual actors.'}),"\n",(0,s.jsx)(n.p,{children:"The integration of the government and cooperative spaces within the RO Wallet\nEcosystem leads to an unified governance of the RO Wallet Ecosystem, grounded\nin European and national legislation that establishes the rules,\nresponsibilities, and incentives necessary for effectively orchestrating an\necosystem comprising diverse independent organizations and individuals. It\nensures the effective utilization of the underlying trust infrastructure,\npromotes value creation for both citizens and organizations, and minimizes\nmisuse through preventive measures and appropriate sanctions. Additionally, a\nkey aspect of orchestration involves communicating and educating stakeholders\nand the broader public about the RO Wallet Ecosystem. These efforts aim to\nensure that the ecosystem is visible and operates in alignment with its\nobjectives, fostering a sustainable and trusted environment."}),"\n",(0,s.jsx)(n.p,{children:"The competition space defines the area where ecosystem actors engage in\ncompetition and differentiation, fostering choice, innovation, and resilience\nthrough multiple offerings within the RO Wallet Ecosystem. The competition\nspace is an integral part of the overall RO Wallet Ecosystem governance, which\nestablishes rules and incentives to ensure fair competition and public\naccountability. At the same time, it strives to maximize market-driven\nmechanisms for the participating actors. In the competition space, three key\nopportunities emerge for innovation in products, services, and\nbusiness/operating models. Organizations can leverage all three options to\ndevelop offerings that deliver value for, through, and on top of the RO Wallet\nEcosystem:"}),"\n",(0,s.jsx)(n.h3,{id:"eudi-wallet-providers",children:"EUDI Wallet Providers"}),"\n",(0,s.jsx)(n.p,{children:"EUDI Wallet Providers offer a EUDI Wallet solution to users, representing a\nproduct and service owned and managed by the eIDAS certified wallet\nprovider. This offering can be provided as a standalone product or extended\nbeyond the certified EUDI Wallet solution that can be characterized as the\nWallet Infrastructure scope. The flexibility of the chosen architecture, which\ncomplies with certification requirements and supports additional features and\nservices beyond the core EUDI Wallet instance, allows EUDI Wallet Providers to\ndifferentiate (e.g. through UX, user related features) themselves and offers\nusers a range of choices."}),"\n",(0,s.jsx)(n.p,{children:"Illustrating Examples:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Instead of offering a standalone app, the EUDI Wallet solution can be\nintegrated into existing consumer-facing applications, such as insurance\xb4s,\nbank\u2019s, airline\u2019s or platform provider branded apps. In doing so, the EUDI\nwallet feature scope and interfaces must be the same to fulfill the upcoming\ncertification requirements and interoperability. To meet upcoming\ncertification requirements and ensure interoperability, the EUDI Wallet's\nfeature scope and interfaces must be the same, regardless of whether\nadditional features beyond the EUDI wallet core are implemented. Features\nspecific to the insurance, banking or airline services that extend beyond the\ncore EUDI Wallet instance are not subject to the eIDAS EUDI wallet\ncertification process. This approach also allows EUDI Wallet providers the\nflexibility to offer additional, potentially chargeable services for users on\ntop of the certified wallet functionality. These added value services are not\npart of the EUDI wallet certification process but might be subject to other\nregulations (e.g. financial services)."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"An existing identity and trust service providers can transition into an EUDI\nWallet Provider, benefiting from the ecosystem's reach and economic synergies\nwith existing services, such as the provision of Qualified Electronic\nSignatures (QES) or Qualified Electronic Attestation of Attributes (QEAA).\nFrom the perspective of existing identity and trust services, the EUDI Wallet\necosystem serves as both a sales channel for established offerings and an\nopportunity to expand business activities through the EUDI wallet,\nparticularly by engaging directly with users (2C market)."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(n.h3,{id:"ecosystem-technology-service-providers",children:"Ecosystem (Technology) Service Providers"}),"\n",(0,s.jsx)(n.p,{children:"Ecosystem (Technology) Service Providers offer products and services that help\norganizations comply with RO Wallet Ecosystem requirements, ensuring active\nparticipation while maximizing value for individual stakeholders. While these\nproviders do not hold an official role within the RO Wallet Ecosystem, they\nhave a critical support function by empowering organizations to effectively\nfulfill their roles (e.g. become a provider or relying party) within the RO\nWallet Ecosystem. They provide their products and services directly to\nindividual organizations and receive financial compensation for the value they\ndeliver. Here, market mechanisms define the success as these actors need to\nconvince other organizations that they provide value."}),"\n",(0,s.jsx)(n.p,{children:"Illustrating Examples:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Conformity Assessment Bodies (CABs) are accredited organizations, authorized\nby the Romanian Accreditation Body (RENAR), responsible for conducting\nassessments that support the certification process for entities such as\n(possible) EUDI wallet providers. By ensuring compliance with the\ncertification scheme, CABs enable organizations to become part of the RO\nWallet Ecosystem. In return for their services, CABs are financially\ncompensated by the organizations utilizing their service."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Technology Service Providers offer organizations products and services to\nensure technical compliance and an easy and quick integration with the RO\nWallet Ecosystem requirements. For example, they might offer products and\nservices to help organisations to register and onboard in the RO Wallet\nEcosystem. Each organization evaluates the value of these offerings and, if\ndeemed beneficial, compensates the technology service provider for the\nproducts or services they utilize."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Consulting Service Providers assist organizations in strategically aligning\nwith and leveraging the RO Wallet Ecosystem to benefit their customers. This\nsupport may include optimizing existing business processes through the\nintegration of RO Wallet and utilizing the advantages offered by the\necosystem. For their advisory and consulting services, they are compensated by\ntheir customers."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(n.h3,{id:"domain-organization-and-governance",children:"Domain organization and governance"}),"\n",(0,s.jsx)(n.p,{children:'For the functioning of the RO Wallet Ecosystem, various attestations are of\ngreat importance. The provision of these attestations is carried out by\nindividual organizations operating in specific domains. Domains are formed by\ngroups of similar or industry-specific use cases. For example, e-prescriptions\nand health insurance applications are part of the "Health" domain, account\nopenings and bank transfers are part of the "Banking" domain. Organizations and\ndomains are responsible for managing their own trust frameworks. These\ndomain-specific trust management mechanisms determine whether a domain-specific\nEAA provider is authorized to issue certain EAAs that are universally accepted\nwithin the domain. This includes defining the requirements for providing EAAs\nwithin the RO Wallet Ecosystem in alignment with domain-specific schemas,\nwhich may be mandated by specific disclosure policies to ensure their seamless\nintegration and usage within the ecosystem. Domain-specific trust management may\nbe shaped and defined by regulations specific to each domain, making compliance\nthe responsibility of the respective domains and the organizations involved. For\nexample, regulations such as PSD2 in the banking sector or AML requirements\nimpose specific obligations that influence how banks interact with the RO\nWallet Ecosystem.'}),"\n",(0,s.jsx)(n.p,{children:"The interplay between the cooperation and competition space highlights the need\nfor individual organizations and domains to develop their own strategy on how to\ninteract with the RO Wallet Ecosystem. This includes defining to aim for an\nactive role within the ecosystem, such as acting as a Relying Party, EAA\nprovider or an EUDI Wallet provider, or focusing more on a supporting role as\ne.g. an Ecosystem (Technology) Service Provider that empowers other\norganizations to leverage the ecosystem effectively. Furthermore, it emphasizes\nthe critical importance of fostering a cooperative space, particularly by\nestablishing a broad public-private acceptance network with diverse use cases.\nThis necessitates contributions from various domains (e.g. financial services,\nhealthcare, mobility and ecommerce) to provide (Q)EAA credentials to the\necosystem, enabling users to access and utilize them through their EUDI wallets.\nIt also empowers relying parties to optimize existing online and offline\nbusiness processes while driving the development of innovative new offerings."}),"\n",(0,s.jsx)(n.p,{children:"The responsibilities within the RO Wallet Ecosystem can be split into I)\nresponsibilities of the ecosystem, II) domain responsibilities and III)\nresponsibilities of individual organizations:"}),"\n",(0,s.jsx)(n.p,{children:"I) Ecosystem responsibilities"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Provide RO Wallet infrastructure including trust management"}),"\n",(0,s.jsx)(n.li,{children:"Harmonize the regulatory framework to ensure the legal operation of the RO\nWallet Ecosystem"}),"\n",(0,s.jsx)(n.li,{children:"Develop and expand the RO Wallet\nEcosystem while facilitating engagement with ecosystem stakeholders and the\nbroader public"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"II) Domain responsibilities"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Develop domain specific strategies to interact with the RO Wallet Ecosystem"}),"\n",(0,s.jsx)(n.li,{children:"Define trust mechanisms and requirements to offer (Q)EAAs to the RO Wallet\nEcosystem"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"III) Organization responsibilities"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Develop organization specific strategies how to interact with the RO Wallet\nEcosystem as relying party and/or EUDI wallet provider"}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"ecosystem-onboarding-consolidating-information-centralizing-access-and-enhancing-transparency-to-prevent-misuse",children:"Ecosystem Onboarding: Consolidating Information, Centralizing Access, and Enhancing Transparency to Prevent Misuse"}),"\n",(0,s.jsx)(n.p,{children:"The eIDAS regulation mandates the registration of organizations interacting\nwith the RO Wallet Ecosystem. This requirement fosters transparency and helps\nprevent misuse or overasking personal data. The ecosystem\nregistration concept centers on the registration of specific use cases and the\ndeclaration of intended uses."}),"\n",(0,s.jsx)(n.p,{children:'The RO Wallet Ecosystem prioritizes robust governance to ensure trust,\nsecurity, and accountability among all ecosystem actors. A key aspect of this\ngovernance requirement is a streamlined ecosystem onboarding process,  which is\nessential for gaining access to the RO Wallet Ecosystem. In line with eIDAS, a "relying party" refers to any legal or natural person intending to\ninteract with the RO Wallet. This term applies universally to organizations\nthat need to register, regardless of whether their intended use involves\nreceiving a PID, obtaining an (Q)EAA, or issuing an (Q)EAA to the ecosystem for\nuse by other actors on behalf of the user.'}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"How organisations join the ecosystem"})}),"\n",(0,s.jsx)(n.p,{children:"Any institution, company or person that wants to request data from your wallet,\nor issue attestations to it, must register first. That way, you always know who\nis asking for your data and why."}),"\n",(0,s.jsx)(n.p,{children:"All relying parties register, such as public services, banks and online shops.\nSo do identity and attestation providers, including qualified ones. Each\nregisters in the country where it is established. A registration made in Romania\nis recognised by wallets across the European Union."}),"\n",(0,s.jsx)(n.p,{children:"For each service in which it wants to use the wallet, the organisation declares\nwhich data it will request and for what purpose. It is not allowed to ask for\nmore. Your wallet shows you what the organisation declared, so you can check\nevery request before you share anything. If an organisation asks for more than\nit declared, or if its registration details are no longer accurate, it can be\nsuspended or removed from the register."}),"\n",(0,s.jsx)(n.p,{children:"In Romania, the Special Telecommunications Service (STS) developed and\nimplemented the national registration system. Once the national legislation is\nadopted, STS will be designated as registrar. The system includes:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"the National Register of Wallet Relying Parties (RNBP)"}),", which will become\npublic after the legislation is adopted: you will be able to look it up at any\ntime, and apps will be able to read it automatically;"]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"the registration portal"}),", where organisations submit and update their details;"]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"access and registration certificates"}),", which let your wallet recognise the\norganisation and check which data it is allowed to request."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Legal basis: Article 5b of Regulation (EU) No 910/2014 (eIDAS), as amended by\nRegulation (EU) 2024/1183, and Commission Implementing Regulation (EU) 2025/848."})}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"The described ecosystem onboarding process is consistent across various use\ncases and organizations seeking access to the RO Wallet Ecosystem. The\nfollowing examples illustrate this process:"})}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"KYC for Financial Services: A bank seeking to receive a PID (Personal\nIdentification Data) for a KYC (Know Your Customer) process must register as a\nrelying party and declare its intended use as \u201cKYC for Anti-Money Laundering,\u201d\nspecifying the required data attributes necessary for its operations. Once the\nregistration process is complete, the bank receives an access certificate for\nthe authentication and a registration certificate for the intended use. During\nthe use case (e.g., opening a bank account), the declared intended use is\ndisplayed to the new customer through his or her RO Wallet. If the requested\ndata exceeds the declared intended use, the user is alerted and the process is\naborted. This mechanism not only informs users but also helps identify\npotential misuse by relying parties."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Pseudonym Login: An eCommerce platform requiring a pseudonymous login from the\nRO Wallet must register as a relying party to obtain an access\ncertificate.This intended use are displayed to the users, ensuring\ntransparency and enabling informed consent."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"QES/Payment authorization: For payment authorization or qualified electronic\nsignature (QES) providers, the process involves registering to request a\ntransaction authorization for authorizing signing contracts or payments. These\nintended uses are displayed to users, ensuring transparency and enabling\ninformed consent."}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsx)(n.p,{children:"Issuing a Diploma: An educational institution, such as a university, aiming to\nissue a diploma to a student after graduation, must register as a relying\nparty and declare its intended use as \u201cProviding a University Diploma.\u201d The\nissuing process must comply with the requirements defined in the institution's\nor domain disclosure policy. This policy specifies the credential requirements\nand is the responsibility of the issuing organization, often influenced by\nregulatory or domain-specific standards. For instance, the education sector\nmay define harmonized issuing requirements to standardize policies across\ninstitutions. This approach applies to other credentials as well, whether they\nare long-term and static (e.g., diplomas) or short-term and dynamic (e.g.,\ncredit scores)."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"The ecosystem registration process facilitates collective oversight by ecosystem\nactors and regulators, leveraging transparency by design. Registered\nparticipants are subject to public monitoring and enforcement processes,\nensuring swift and effective responses to violations. This collective approach\nstrengthens trust within the ecosystem and promotes broader adoption by ensuring\nsecure and reliable ecosystem interactions. The following examples illustrate\nhow maximizing transparency effectively balances the flexibility required for\necosystem adoption with robust safeguards against misuse:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Use-case restriction and user warnings: The RO Wallet only permits relying\nparties to offer use cases that are explicitly registered after receiving the\naccess and registration certificate. If a mismatch occurs, users are\nproactively warned. However, users retain the ability to proceed based on\ntheir individual decisions, provided they make an active and informed choice."}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"level-playing-field-regulation-the-foundation-for-user-choice-and-fair-competition-among-ecosystem-actors",children:"Level-Playing Field Regulation: The Foundation for User Choice and Fair Competition Among Ecosystem Actors"}),"\n",(0,s.jsx)(n.p,{children:"The RO Wallet Ecosystem comprises multiple actors that must be aligned and\ninterconnected. A critical factor for creating value is scaling the acceptance\nnetwork within the cooperative space to expand the ecosystem's reach.\nEstablishing this acceptance network is essential for overcoming fragmentation,\nwhich often impedes user choice, fair competition, and scalability. For\ninstance, EUDI wallet providers face challenges in sourcing credentials from\ndiverse providers and ensuring that relying parties effectively utilize these\ncredentials in various business use cases. This is crucial for creating value\nfor users who hold the credentials and for convincing them that the EUDI Wallet\nprovider\u2019s offering delivers tangible benefits. Therefore, alongside the\ntechnical and organizational development of the RO Wallet acceptance network,\na regulatory cornerstone is essential: an \u201cLevel-Playing Field.\u201d"}),"\n",(0,s.jsx)(n.p,{children:"This framework ensures non-discriminatory access for all ecosystem actors,\nincluding EAA providers, EUDI Wallet providers, and relying parties. This\nregulatory principle enhances the acceptance reach by ensuring that all\necosystem actors benefit from each other's individual activities, which align\nwith collective interests of the cooperative space. It also lays the groundwork\nfor fair competition within the ecosystem by preventing any dominant\nplayer - whether the government or a powerful non-government actor - from\nmonopolizing the acceptance network. This safeguard ensures that the RO Wallet\nEcosystem, built on the digital public wallet infrastructure and its acceptance\nnetwork, cannot be exploited for private value capture at the expense of\ncompetitors and users. Therefore, it ensures the collective public interest by\npreventing monopolization attempts that could arise from the \u201cwinner-takes-all\u201d\ndynamics of the RO Wallet Ecosystem. These dynamics are driven by the\nunderlying network effects and are well-known from network infrastructures (e.g.\ntelecommunication) and digital platform markets (e.g. mobile payments)"}),"\n",(0,s.jsx)(n.p,{children:"As outlined in Section 4: Splitting Responsibilities for defining the boundaries\nof the \u201cLevel-Playing-Field\u201d regulation a differentiation in the ecosystem\noperating model and individual business models of Ecosystem Technology Service\nProviders and Qualified Trust Service Providers is needed. The\n\u201cLevel-Playing-Field\u201d regulation applies to the ecosystem operating model, while\nthe business relationships of Ecosystem Technology Service Providers/Qualified\nTrust Service Providers and actors that participate in the EU wallet ecosystem\nare governed by market mechanisms and fall outside the scope of the RO Wallet\nEcosystem's governance. The business model for Ecosystem Technology Service\nProviders and Qualified Trust Service Providers focuses on delivering products\nand services that enable organizations to engage with and participate in the\nRO Wallet Ecosystem. These providers are compensated for their offerings by\nthe individual organizations with whom they have established business\nrelationships. Figure 2 illustrates these interrelationships."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.img,{alt:"Level-Playing-Field\nRegulation.",src:i(3593).A+"",width:"1728",height:"831"})}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Figure 6: Differentiation Between Level-Playing-Field Regulation and Market\nMechanisms"})}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:'Illustrating Exemples of the "Level-Playing Field" regulation'})}),"\n",(0,s.jsx)(n.p,{children:'Part of the \u201cLevel-Playing Field\u201d regulation is that all EAA providers, EUDI\nwallet providers and relying parties need to register to get access to the\necosystem. To demonstrate the\nconcept of the "Level-Playing Field" three illustrative examples are described:'}),"\n",(0,s.jsx)(n.p,{children:"A Bank is using a PID for a KYC to enable users to open a bank account:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:'In this case, the \u201cLevel-Playing-Field\u201d regulation ensures that all EUDI\nwallet providers have equal acceptance network reach. A bank uses a PID\n(Personal Information Data) for KYC (Know Your Customer) purposes to enable\nusers to open a bank account. In the context of the RO Wallet Ecosystem, the\nbank interacts with all certified EUDI Wallet providers. From an integration\nand user experience perspective, a "Do it with my RO Wallet" button will be\navailable to seamlessly initiate the process. This ensures that users have the\nfreedom to choose their preferred wallet provider, granting them ecosystem\naccess through the acceptance network. Unlike the current reality where banks\noften select a specific identity service provider as their KYC partner, the\nRO Wallet Ecosystem shifts this power dynamic. Here, users bring their\nchosen "EUDI Wallet provider" to the bank, reflecting the user-centric\napproach. The bank can rely on the RO Wallet certification and the\naccompanying ecosystem governance to ensure that all providers meet the\nnecessary regulatory requirements for KYC compliance. According to the\nprinciples of the "Level-Playing-Field" regulation, banks are prohibited from\nexclusively partnering with specific EUDI Wallet providers. This also helps\nprevent scenarios where a bank that is also an EUDI wallet provider could\nfavor its own offering and effectively \u201cprivatize\u201d the public ecosystem.\nTherefore, this restriction is vital to maintaining fair competition among\nwallet providers and safeguarding user choice, fostering a balanced and open\necosystem.'}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"An EAA Provider is issuing an Airline ticket or an Education diploma to enable\nusers to hold the credential in their RO Wallet:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"In this case, the \u201cLevel-Playing-Field\u201d regulation ensures that users can hold\nand manage their credentials in their RO Wallet, regardless of the specific\nwallet provider they choose. EAA Providers, such as airlines or educational\ninstitutions, are required to interact with all certified EUDI Wallet\nproviders. They are prohibited from selecting or favoring a preferred partner,\nas this decision lies solely with the user. This approach prevents ecosystem\nfragmentation and monopolization while guaranteeing interoperability, which is\nessential for fostering fair competition and preserving user choice. From the\nuser\u2019s perspective, the \u201cLevel-Playing Field\u201d ensures that EAAs issued by any\nprovider can be seamlessly utilized, enabling a consistent and user-friendly\nexperience across the ecosystem. However, it is the responsibility of the EAA providers to establish their\nissuing policies and define their business conditions for providing an EAA."}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"An EUDI Wallet Provider needs to accept all EAAs from all providers and serve\nall relying parties that are part of the RO Wallet Ecosystem:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"In this case, the \u201cLevel-Playing-Field\u201d regulation ensures that users can\ntrust their EUDI wallet provider to service all EAA Providers and Relying\nParties that are part of the RO Wallet Ecosystem and the underlying\nacceptance network. This ensures a seamless and inclusive experience for\nusers, regardless of the source of their credentials or the relying party they\nwish to interact with. This obligation prevents exclusivity and favoritism,\nupholds user choice and fair competition, and ensures that all ecosystem\nactors operate on an level-playing field. However, based on eIDAS\nregulation the EUDI wallet providers only get access to the PID of the Member\nState they are certified in."}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Implementing the \u201cLevel-Playing-Field\u201d Regulation and Implications for EUDI\nWallet Provider Business Models"})}),"\n",(0,s.jsx)(n.p,{children:"The \u201cLevel-Playing-Field\u201d Regulation is a core principle of the RO Wallet\nEcosystem and all ecosystem actors (public and private) and all ecosystem roles\n(Provider, EUDI wallet provider, Relying Party) are obliged to the requirement."}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Implication for potential providers to offer the EUDI Wallets free of charge"})}),"\n",(0,s.jsx)(n.p,{children:'The eIDAS regulation mandates that EUDI wallets must be provided free of\ncharge to natural persons. To ensure an level-playing field while promoting\ndifferentiation and competition among EUDI wallet providers, the\nregulatory-defined scope of the wallet plays a pivotal role (see Section 4:\nSplitting Responsibilities). This scope establishes the foundational features\nand interoperability requirements necessary to uphold the principles of the\n"Level-Playing Field" regulation. While the core scope of the RO Wallet falls\nunder the eIDAS requirement for free access, providers are permitted to\ndevelop additional services and features beyond this core. These value-added\nofferings are not subject to the eIDAS regulation and its corresponding\ncertification and may form the basis of chargeable services, enabling providers\nto establish sustainable business models. From the user\u2019s perspective, wallet\napplications will include the regulated core features to ensure security and\nprivacy but may also offer enhanced functionalities and services beyond the RO\nWallet scope, tailored to specific needs and use cases. More details and\nexamples are described in Section 4: Splitting Responsibilities.'}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Implication for legal relationships between ecosystem roles"}),' The outlined\n"Level-Playing-Field" regulation principles necessitate defining legal\nrelationships between roles at the ecosystem level. This ensures that legal\nissues are not determined on a case-by-case basis between individual\norganizations and roles. Instead, the RO Wallet Ecosystem will operate under a\nharmonized legal framework, which requires further detailed definition.']}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Implication for potential EUDI wallet providers to provide Qualified\nElectronic Signatures (QES) for non-professional use free of charge"})}),"\n",(0,s.jsx)(n.p,{children:'The eIDAS regulation mandates that EUDI wallets must enable the user to sign by means of Qualified\nElectronic Signatures (QES) free of charge for non-professional purposes. This\napplies to the RO Wallet-centric QES scenario, where the management of\nqualified certificates is integrated into the RO Wallet. Differentiating between professional and non-professional usage\npresents a challenge and requires further work such as defining a dedicated national attribute in the National Register of Wallet Relying Parties (RNBP), separate from the "IntendedUse" and "Entitlements" fields, to carry the professional/non-professional signing context.'}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Implication for smartphone manufacturers to ensure fair competition with third\nparty EUDI wallet providers"})}),"\n",(0,s.jsx)(n.p,{children:'From the perspective of EUDI wallet providers, the "Level-Playing-Field"\nregulation must prioritize ensuring the visibility and accessibility of wallet\noptions for potential users. Smartphone manufacturers, who can pre-install an\n(EUDI) wallet offering as part of their operating system, gain a significant\ncompetitive advantage, as these wallets are readily available during the initial\ndevice setup. To uphold the "Level-Playing-Field" principle, it is crucial to\nprohibit exclusive bundling practices that unfairly benefit smartphone\nmanufacturers at the expense of third-party competitors. Users must have the\nfreedom to select their preferred EUDI wallet provider, following a model\nsimilar to the browser choice approach in the European Union. Additionally,\ncompeting EUDI wallet providers must be granted access to critical smartphone\ninfrastructure functions and user features utilized by the incumbent RO Wallet\n(e.g. double tap on iPhones). Achieving this requires proactive action from\nnational and European regulators to establish fair competition within the RO\nWallet Ecosystem. Through industry dialogue and regulatory instruments, such as\nthe Digital Markets Act, these measures must be achieved to ensure fair\ncompetition and lay the foundation for a balanced and open ecosystem where all\nEUDI wallet providers have fair opportunities to compete leading to choice for\ncitizens.'})]})}function h(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},5301(e,n,i){const t=i.p+"assets/images/EGOM_Figure 1_Three Spaces-af196876e291bcec99a66aa3c448aaae.png";i.d(n,["A",0,t])},3593(e,n,i){const t=i.p+"assets/images/EGOM_Figure 6_Equal Level Playing Field-5e2403367ae494499d7b62096aa82958.png";i.d(n,["A",0,t])},8453(e,n,i){i.d(n,{R:()=>r,x:()=>o});var t=i(6540);const s={},a=t.createContext(s);function r(e){const n=t.useContext(a);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),t.createElement(a.Provider,{value:n},e.children)}}}]);